// Original local canvas effects inspired by the referenced interaction styles.
const KEY='monday-atmosphere-v2';
export function readAtmosphere(){try{const c=JSON.parse(localStorage.getItem(KEY)||'{}');return{mode:['auto','dots','waves','glyphs','stars','orbits','off'].includes(c.mode)?c.mode:'auto'}}catch{return{mode:'auto'}}}
export function saveAtmosphere(value){localStorage.setItem(KEY,JSON.stringify({mode:value.mode}));window.dispatchEvent(new CustomEvent('monday-atmosphere-change',{detail:value}))}
export function createIntroExperience(React){return function IntroExperience({Wordmark}){return React.createElement(Wordmark)}}
export function mountAtmosphere(root=document.getElementById('root')){if(!root)return()=>{};const canvas=document.createElement('canvas');canvas.className='monday-live-background';canvas.setAttribute('aria-hidden','true');root.prepend(canvas);const ctx=canvas.getContext('2d');if(!ctx){canvas.remove();return()=>{}}const reduced=matchMedia('(prefers-reduced-motion: reduce)');let config={mode:'auto'},w=0,h=0,frame=null,last=0,start=performance.now(),home=false;const modes=['dots','waves','glyphs','stars','orbits'];function resize(){w=innerWidth;h=innerHeight;const d=Math.min(devicePixelRatio||1,1.5);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);draw(0)}function pattern(mode,t,alpha){ctx.globalAlpha=alpha;ctx.fillStyle='#c7c7c7';ctx.strokeStyle='#b5b5b5';ctx.lineWidth=.6;if(mode==='dots'){for(let x=14;x<w;x+=30)for(let y=14;y<h;y+=30){const a=.12+.3*(.5+.5*Math.sin(x*.009+y*.01-t*.65));ctx.globalAlpha=alpha*a;ctx.beginPath();ctx.arc(x,y,1+Math.sin(x*.005+t)*.3,0,Math.PI*2);ctx.fill()}}if(mode==='waves'){for(let j=0;j<18;j++){ctx.beginPath();for(let x=0;x<=w;x+=14){const y=h*.55+j*13+Math.sin(x*.004+t*.35+j*.15)*65+Math.cos(x*.001-t*.2)*40;x?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke()}}if(mode==='glyphs'){ctx.font='10px monospace';for(let x=18;x<w;x+=42)for(let j=0;j<8;j++){const y=((j*110+x*.73+t*(9+(x%3)))%(h+100))-50;ctx.globalAlpha=alpha*(.1+(j%3)*.08);ctx.fillText('.:+01'[Math.floor(x+j)%5],x,y)}}if(mode==='stars'){const points=Array.from({length:55},(_,i)=>({x:(Math.sin(i*76.3)*.5+.5)*w+Math.sin(t*.14+i)*8,y:(Math.cos(i*32.7)*.5+.5)*h+Math.cos(t*.12+i)*8}));for(let i=0;i<points.length;i++){const p=points[i];ctx.beginPath();ctx.arc(p.x,p.y,1.2,0,Math.PI*2);ctx.fill();for(let j=i+1;j<points.length;j++){const q=points[j],d=Math.hypot(q.x-p.x,q.y-p.y);if(d<125){ctx.globalAlpha=alpha*(1-d/125)*.5;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke()}}ctx.globalAlpha=alpha}}if(mode==='orbits'){for(let i=0;i<12;i++){ctx.beginPath();ctx.ellipse(w*.5,h*.5,70+i*34,25+i*16,Math.sin(t*.05)*.4,0,Math.PI*2);ctx.stroke();const a=t*.1+i;ctx.beginPath();ctx.arc(w*.5+Math.cos(a)*(70+i*34),h*.5+Math.sin(a)*(25+i*16),1.5,0,Math.PI*2);ctx.fill()}}ctx.globalAlpha=1}
function draw(t){ctx.clearRect(0,0,w,h);if(!home||config.mode==='off')return;const mode=config.mode==='auto'?modes[Math.floor(t/24)%5]:config.mode;const fade=config.mode==='auto'?Math.min(1,(t%24)/2):1;pattern(mode,t,.65*fade);if(config.mode==='auto'&&fade<1)pattern(modes[(Math.floor(t/24)+4)%5],t,.65*(1-fade))}function tick(now){frame=null;if(document.hidden||!home||config.mode==='off')return;if(now-last>1000/24){draw((now-start)/1000);last=now}if(!reduced.matches)frame=requestAnimationFrame(tick)}function wake(){if(frame!==null)cancelAnimationFrame(frame);frame=null;const surface=root.querySelector('.muse-home-simple');home=!!surface;if(surface&&canvas.parentElement!==surface)surface.prepend(canvas);canvas.style.display=home?'block':'none';if(home&&!document.hidden&&config.mode!=='off'){if(reduced.matches)draw(3);else frame=requestAnimationFrame(tick)}}function changed(e){config={mode:'auto'};wake()}const observer=new MutationObserver(()=>{const next=!!root.querySelector('.muse-home-simple');if(next!==home||(next&&canvas.parentElement!==root.querySelector('.muse-home-simple')))wake()});observer.observe(root,{childList:true,subtree:true});window.addEventListener('resize',resize,{passive:true});window.addEventListener('monday-atmosphere-change',changed);document.addEventListener('visibilitychange',wake);reduced.addEventListener('change',wake);resize();wake();return()=>{if(frame!==null)cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('resize',resize);window.removeEventListener('monday-atmosphere-change',changed);document.removeEventListener('visibilitychange',wake);reduced.removeEventListener('change',wake);canvas.remove()}}
